module tb;
    reg  [2:0] sel;
    reg  [3:0] data0, data1, data2, data3, data4, data5;
    wire [3:0] out;

    TopModule uut (
        .sel(sel),
        .data0(data0),
        .data1(data1),
        .data2(data2),
        .data3(data3),
        .data4(data4),
        .data5(data5),
        .out(out)
    );

    initial begin
        data0 = 4'h1;
        data1 = 4'h2;
        data2 = 4'h3;
        data3 = 4'h4;
        data4 = 4'h5;
        data5 = 4'h6;

        for (int i = 0; i < 8; i++) begin
            sel = i[2:0];
            #1;
            if (i <= 5) begin
                if (out !== i[3:0] + 4'd1) begin
                    $display("SELFTEST FAIL: sel=%0d, expected=%0d, got=%0d", i, i+1, out);
                    $finish;
                end
            end else begin
                if (out !== 4'h0) begin
                    $display("SELFTEST FAIL: sel=%0d (default), expected=0, got=%0d", i, out);
                    $finish;
                end
            end
        end

        $display("SELFTEST PASS");
        $finish;
    end
endmodule
